package com.rpb.reservation.workforce;

import com.rpb.reservation.workforce.statutory.*;
import com.rpb.reservation.workforce.statutory.StatutoryDtos.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class AdditionalWagesCalculatorTest {
 final StatutoryCalculator calculator=new StatutoryCalculator();
 final CpfProfile citizen=new CpfProfile("citizen",LocalDate.of(1990,1,1),null,"GG","");
 BigDecimal d(String x){return new BigDecimal(x);}
 Result calc(String ow,String aw,String eligible){return calculator.calculateMonthly(YearMonth.of(2026,10),citizen,d(ow),d(aw),d(eligible),OfficialStatutoryTemplates.forYearWithAw(2026).config());}
 @Test void officialSameMonthOracleRoundsOneFullTarget(){var r=calc("1004","101","101");assertThat(r.employeeCpf()).isEqualByComparingTo("221");assertThat(r.employerCpf()).isEqualByComparingTo("188");}
 @Test void rawBandSurvivesZeroAndSmallAwQuota(){var r=calc("500","1000","100");assertThat(r.employeeCpf()).isEqualByComparingTo("120");assertThat(r.employerCpf()).isEqualByComparingTo("102");assertThat(calc("500","1000","0").employeeCpf()).isEqualByComparingTo("100");}
 @Test void separateCapsDoNotApplyOwCeilingToAw(){var r=calc("9000","10000","6000");assertThat(r.cpfWages()).isEqualByComparingTo("14000");assertThat(r.employeeCpf()).isEqualByComparingTo("2800");}
 @Test void officialLowWageAndDerivedLinearOracles(){assertThat(calc("400","100","100").employerCpf()).isEqualByComparingTo("85");var ramp=calc("400","200","200");assertThat(ramp.employeeCpf()).isEqualByComparingTo("60");assertThat(ramp.employerCpf()).isEqualByComparingTo("102");assertThat(calc("500","250","250").employerCpf()).isEqualByComparingTo("128");assertThat(calc("400","100","40").employerCpf()).isEqualByComparingTo("75");assertThat(calc("40","60","0").employerCpf()).isEqualByComparingTo("7");assertThat(calc("40","10","0").employerCpf()).isZero();assertThatThrownBy(()->calc("400","200","100")).hasMessage("AW_RAMP_CAP_UNSUPPORTED");}
 @Test void v1CannotSilentlyComputeAwButForeignNeedsNoQuota(){assertThatThrownBy(()->calculator.calculateMonthly(YearMonth.of(2026,10),citizen,d("1000"),d("100"),d("100"),OfficialStatutoryTemplates.forYear(2026).config())).hasMessage("STATUTORY_CAPABILITY_UNSUPPORTED");var r=calculator.calculateMonthly(YearMonth.of(2026,10),new CpfProfile("foreign",null,null,"GG",""),d("500"),d("500"),null,OfficialStatutoryTemplates.forYear(2026).config());assertThat(r.employeeCpf()).isZero();assertThat(r.sdl()).isEqualByComparingTo("2.5");}
 @Test void awZeroRetainsV1AcrossFiveTablesAgesAndThresholds(){for(String dob:List.of("1990-01-01","1968-01-01","1963-01-01","1958-01-01","1950-01-01"))for(String table:List.of("T1","T2","T3","T4","T5")){var p=table.equals("T1")?new CpfProfile("citizen",LocalDate.parse(dob),null,"GG",""):new CpfProfile("spr",LocalDate.parse(dob),LocalDate.of(Set.of("T2","T4").contains(table)?2026:2025,1,1),Set.of("T4","T5").contains(table)?"FG":"GG","evidence");for(String wage:List.of("0","50","50.01","500","500.01","600","750","750.01","1003.27","9000")){var a=calculator.calculate(YearMonth.of(2026,10),p,d(wage),d(wage));var b=calculator.calculateMonthly(YearMonth.of(2026,10),p,d(wage),BigDecimal.ZERO,BigDecimal.ZERO,OfficialStatutoryTemplates.forYearWithAw(2026).config());assertThat(b.employeeCpf()).isEqualByComparingTo(a.employeeCpf());assertThat(b.employerCpf()).isEqualByComparingTo(a.employerCpf());}}}
 @Test void positiveAwUsesEveryTableAndAgeAndSameMonthSplitIsEquivalent(){for(String birth:List.of("1990-01-01","1968-01-01","1963-01-01","1958-01-01","1950-01-01"))for(int table=1;table<=5;table++){var dob=LocalDate.parse(birth);var profile=table==1?new CpfProfile("citizen",dob,null,"GG",""):new CpfProfile("spr",dob,LocalDate.of(table==2||table==4?2026:2025,1,1),table>=4?"FG":"GG","approved election");for(String tw:List.of("50","50.01","500","500.01","600","750","750.01","1105")){var total=d(tw);var aw=total.divide(new BigDecimal("2"));var ow=total.subtract(aw);var actual=calculator.calculateMonthly(YearMonth.of(2026,10),profile,ow,aw,aw,OfficialStatutoryTemplates.forYearWithAw(2026).config());var baseline=calculator.calculate(YearMonth.of(2026,10),profile,total,total);assertThat(actual.employeeCpf()).isEqualByComparingTo(baseline.employeeCpf());assertThat(actual.employerCpf()).isEqualByComparingTo(baseline.employerCpf());}}var before=calc("1004","0","0");var first=calc("1004","50.50","50.50");var last=calc("1004","101","101");assertThat(first.employeeCpf().subtract(before.employeeCpf()).add(last.employeeCpf().subtract(first.employeeCpf()))).isEqualByComparingTo("21");assertThat(first.employerCpf().subtract(before.employerCpf()).add(last.employerCpf().subtract(first.employerCpf()))).isEqualByComparingTo("17");}
}
